import { Component, forwardRef, input } from '@angular/core';
import { FormsModule, NG_VALUE_ACCESSOR } from '@angular/forms';
import { NzInputNumberModule } from 'ng-zorro-antd/input-number';
import { HrmControl } from '../shared/hrm-control';
import { HrmSize, HrmStatus, toNzStatus } from './hrm-input';

const toNz = (s: HrmSize) => (s === 'sm' ? 'small' : s === 'lg' ? 'large' : 'default');

/** hrm-input-number — nhập số bọc nz-input-number + CVA (min/max/step, format).
 *  unit: hậu tố đơn vị hiển thị cuối ô (VD '%', 'ngày', 'giờ'); mặc định '' (ẩn). */
@Component({
  selector: 'hrm-input-number',
  imports: [FormsModule, NzInputNumberModule],
  template: `
    <nz-input-number
      [ngModel]="value()"
      (ngModelChange)="emit($event)"
      (nzBlur)="markTouched()"
      [nzMin]="min()"
      [nzMax]="max()"
      [nzStep]="step()"
      [nzPrecision]="precision()"
      [nzSize]="toNz(size())"
      [nzStatus]="toNzStatus(status())"
      [nzDisabled]="disabled()"
      [nzPlaceHolder]="placeholder()"
      [nzFormatter]="formatter"
      [nzParser]="parser"
      style="width:100%"></nz-input-number>
  `,
  host: { class: 'hrm-input-number', '[class.hrm-status-success]': "status() === 'success'" },
  providers: [{ provide: NG_VALUE_ACCESSOR, useExisting: forwardRef(() => HrmInputNumber), multi: true }],
})
export class HrmInputNumber extends HrmControl<number> {
  readonly placeholder = input('');
  readonly size = input<HrmSize>('md');
  readonly status = input<HrmStatus>('');
  readonly min = input<number>(-Infinity);
  readonly max = input<number>(Infinity);
  readonly step = input<number>(1);
  /** số chữ số thập phân (null = không ép). */
  readonly precision = input<number | null>(null);
  /** hậu tố đơn vị cuối ô, VD '%'. Mặc định '' = không hiển thị đơn vị. */
  readonly unit = input('');
  protected readonly toNz = toNz;
  protected readonly toNzStatus = toNzStatus;

  protected readonly formatter = (v: number): string => {
    if (v == null || isNaN(v)) return '';
    const u = this.unit();
    return u ? `${v} ${u}` : `${v}`;
  };
  protected readonly parser = (v: string): number => {
    const raw = v.replace(/[^\d.-]/g, '');
    return raw === '' || raw === '-' ? 0 : Number(raw);
  };
}
